#include <vector>
#include <string>

class Solution {
public:
    std::vector<int> lastVisitedCell(std::vector<std::string>& grid) {
        int m = grid.size(), n = grid[0].size();
        std::vector<std::vector<bool>> visited(m, std::vector<bool>(n, false));

        int r = 0, c = 0;
        while (true) {
            visited[r][c] = true;
            int dr = 0, dc = 0;
            char ch = grid[r][c];
            if (ch == 'R') dc = 1;
            else if (ch == 'L') dc = -1;
            else if (ch == 'D') dr = 1;
            else if (ch == 'U') dr = -1;

            int nr = r + dr, nc = c + dc;
            if (nr < 0 || nr >= m || nc < 0 || nc >= n || visited[nr][nc]) {
                return {r, c};
            }
            r = nr; c = nc;
        }
    }
};

class Solution {
    public int[] lastVisitedCell(String[] grid) {
        int m = grid.length, n = grid[0].length();
        boolean[][] visited = new boolean[m][n];

        int r = 0, c = 0;
        while (true) {
            visited[r][c] = true;
            int dr = 0, dc = 0;
            char ch = grid[r].charAt(c);
            if (ch == 'R') dc = 1;
            else if (ch == 'L') dc = -1;
            else if (ch == 'D') dr = 1;
            else if (ch == 'U') dr = -1;

            int nr = r + dr, nc = c + dc;
            if (nr < 0 || nr >= m || nc < 0 || nc >= n || visited[nr][nc]) {
                return new int[]{r, c};
            }
            r = nr; c = nc;
        }
    }
}

